	Ref  string // full ref name, e.g. refs/entire/checkpoints/ab/3c4d5e6f70/tree
	Hash plumbing.Hash
}

// migrateRefsResult is the summary of a run.
type migrateRefsResult struct {
	Created int
	Skipped int
	Total   int
}
```

