39	// buildCheckpointList walks the entire/checkpoints/v1 branch tree and returns
40	// one entry per checkpoint. A missing v1 branch yields an empty list (no error).
41	func buildCheckpointList(ctx context.Context, repo *git.Repository) ([]checkpointEntry, error) {
42		branch := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
43		ref, err := repo.Reference(branch, true)
44		if err != nil {
45			// No v1 branch -> nothing to migrate.
46			return nil, nil //nolint:nilerr // absent branch is an empty list, not an error
47		}
48		commit, err := repo.CommitObject(ref.Hash())
49		if err != nil {
50			return nil, fmt.Errorf("resolve v1 commit: %w", err)
51		}
52		tree, err := commit.Tree()
53		if err != nil {
54			return nil, fmt.Errorf("resolve v1 tree: %w", err)
55		}
56	
57		var entries []checkpointEntry
58		walkErr := checkpoint.WalkCheckpointShards(ctx, repo, tree, func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error {
59			entries = append(entries, checkpointEntry{ID: cpID, Tree: cpTreeHash})
60			return nil
61		})
62		if walkErr != nil {
63			return nil, fmt.Errorf("walk checkpoint shards: %w", walkErr)
64		}
65		return entries, nil
66	}
