68	// writeCacheFile writes one "<id>\t<treeHash>" line per entry, creating parent
69	// directories as needed.
70	func writeCacheFile(path string, entries []checkpointEntry) error {
71		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
72			return fmt.Errorf("create cache dir: %w", err)
73		}
74		var buf bytes.Buffer
75		for _, e := range entries {
